SELECT id, store_id, AVG(revenue) OVER (ORDER BY sale_date, id ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS revenue_avg_6_prior, NTILE(10) OVER (PARTITION BY store_id ORDER BY revenue, id) AS revenue_bucket, AVG(units) OVER (PARTITION BY store_id, product_id ORDER BY revenue, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS units_avg_2, CORR(units, revenue) OVER (PARTITION BY store_id, product_id) AS corr_units_revenue FROM store_sales WHERE product_id = 8;
